import unicodedata


def is_palindrome(s: str) -> bool:
    if s == "":
        raise ValueError("empty string has no palindrome status")
    t = unicodedata.normalize("NFC", s).casefold()
    t = "".join(c for c in t if c.isalnum())
    return t == t[::-1]
